    </ul>
}

@code {
    private List<Notification> notifications = [];
    private CancellationTokenSource? _cts;
    private int _lastSeenId;

    [PersistentState]
    public List<Notification>? PersistedNotifications { get; set; }

    protected override void OnInitialized()
    {
        if (PersistedNotifications is not null)
        {
            // Restored from prerender — skip the service call
            notifications = PersistedNotifications;
        }
        else
        {
            notifications = NotificationSvc.GetAll();
            PersistedNotifications = notifications;
        }

        _lastSeenId = notifications.Count > 0 ? notifications.Max(n => n.Id) : 0;
    }

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            // OnAfterRender never fires during prerender,
            // so this is safe to start the polling loop.
            _cts = new CancellationTokenSource();
            _ = PollForNotificationsAsync(_cts.Token);
        }

        await Task.CompletedTask;
    }

    private async Task PollForNotificationsAsync(CancellationToken ct)
    {
        while (!ct.IsCancellationRequested)
        {
            await Task.Delay(TimeSpan.FromSeconds(5), ct).ConfigureAwait(false);

            var newItems = NotificationSvc.GetSince(_lastSeenId);
            if (newItems.Count > 0)
            {
                _lastSeenId = newItems.Max(n => n.Id);
                await InvokeAsync(() =>
                {
                    notifications.AddRange(newItems);
                    StateHasChanged();
                });
            }
        }
    }

    public async ValueTask DisposeAsync()
    {
        if (_cts is not null)
        {
            await _cts.CancelAsync();
            _cts.Dispose();
        }
    }
}

